class Gradebook:
    def __init__(self) -> None:
        self.assignments = {}  # name -> (weight, kind)
        self.grades = {}  # student -> {assignment -> grade}

    def add_assignment(self, name: str, weight: float, kind: str = "homework") -> None:
        """kind is "homework" or "quiz"."""
        if kind not in ["homework", "quiz"]:
            raise ValueError(f"kind must be 'homework' or 'quiz', got '{kind}'")
        self.assignments[name] = (weight, kind)

    def record(self, student: str, assignment: str, grade: float) -> None:
        if grade < 2.0 or grade > 5.0:
            raise ValueError(f"Grade {grade} is outside the valid range [2.0, 5.0]")
        if assignment not in self.assignments:
            raise ValueError(f"Assignment '{assignment}' not found")

        if student not in self.grades:
            self.grades[student] = {}
        self.grades[student][assignment] = grade

    def average(self, student: str) -> float:
        if student not in self.grades:
            return 0.0

        student_grades = self.grades[student]

        # Get all assignments for this student that have been recorded
        recorded_assignments = []
        for assignment in student_grades:
            if assignment in self.assignments:
                recorded_assignments.append(assignment)

        if not recorded_assignments:
            return 0.0

        # Separate homework and quiz grades
        homework_grades = []
        quiz_grades = []

        for assignment in recorded_assignments:
            grade = student_grades[assignment]
            weight, kind = self.assignments[assignment]
            if kind == "homework":
                homework_grades.append((grade, weight))
            elif kind == "quiz":
                quiz_grades.append((grade, weight))

        # Handle quiz dropping: if more than one quiz, drop the lowest grade
        if len(quiz_grades) > 1:
            # Sort by grade to find the lowest
            quiz_grades.sort(key=lambda x: x[0])
            # Drop the lowest grade (first element after sorting)
            quiz_grades = quiz_grades[1:]

        # Calculate weighted sum and total weight
        weighted_sum = 0.0
        total_weight = 0.0

        for grade, weight in homework_grades:
            weighted_sum += grade * weight
            total_weight += weight

        for grade, weight in quiz_grades:
            weighted_sum += grade * weight
            total_weight += weight

        # Handle case where total_weight is 0 (shouldn't happen with valid data, but safe)
        if total_weight == 0.0:
            return 0.0

        average_grade = weighted_sum / total_weight
        return round(average_grade, 2)
